L2_logistics_invoice.invariants_dsl:
spec LogisticsInvoice {
    field cargo_type: String {
        value IN ["Industrial Equipment", "Raw Materials", "Electronics"];
    }
    field weight_kg: Number {}
    field unit_rate_per_kg: Number {}
    field base_cost: Number {
        value == this.weight_kg * this.unit_rate_per_kg;
    }
    field fuel_surcharge: Number {
        value == this.base_cost * 0.12;
    }
    field customs_duty: Number {
        value == this.base_cost * 0.05;
    }
    field total_invoice_usd: Number {
        value == this.base_cost + this.fuel_surcharge + this.customs_duty;
    }
    invariant cargo_constraints {
        this.weight_kg >= 10.0;
        this.weight_kg <= 10000.0;
        this.unit_rate_per_kg >= 1.5;
        this.unit_rate_per_kg <= 50.0;
    }
}

L2_payroll_stub.invariants_dsl:
spec PayrollStub {
    field employee_id: String {}
    field hours_worked: Number {}
    field hourly_rate: Number {}
    field gross_pay: Number {
        value == this.hours_worked * this.hourly_rate;
    }
    field income_tax: Number {
        value == this.gross_pay * 0.22;
    }
    field pension_deduction: Number {
        value == this.gross_pay * 0.05;
    }
    field net_pay: Number {
        value == this.gross_pay - (this.income_tax + this.pension_deduction);
    }
    invariant payroll_limits {
        this.hours_worked >= 1.0;
        this.hours_worked <= 80.0;
        this.hourly_rate >= 15.0;
        this.hourly_rate <= 250.0;
    }
}

L2_retail_order_billing.invariants_dsl:
spec OrderBilling {
    field sku_id: String {}
    field quantity: Integer {}
    field unit_price: Number {}
    field subtotal: Number {
        value == this.unit_price * this.quantity;
    }
    field discount_rate: Number {
        value == 0.10;
    }
    field discount_amount: Number {
        value == this.subtotal * this.discount_rate;
    }
    field taxable_amount: Number {
        value == this.subtotal - this.discount_amount;
    }
    field tax_amount: Number {
        value == this.taxable_amount * 0.08;
    }
    field final_total: Number {
        value == this.taxable_amount + this.tax_amount;
    }
    invariant quantity_bounds {
        this.quantity >= 1;
        this.quantity <= 50;
        this.unit_price >= 5.0;
        this.unit_price <= 500.0;
    }
}
